	private static void assertExactJournal(Path path, List<Statement> supplied, boolean addition, long previous,
			UUID generation) throws IOException {
		byte[] actualBytes;
		try (GZIPInputStream input = new GZIPInputStream(Files.newInputStream(path))) {
			actualBytes = input.readAllBytes();
		}
		var journal = LmdbBackupDeltaCodec.readJournal(new ByteArrayInputStream(actualBytes));
		assertEquals(previous, journal.previousTransactionId());
		assertEquals(generation, journal.generation());
		assertEquals(supplied.size(), journal.records().size());
		Map<Resource, Statement> remaining = new HashMap<>();
		for (Statement statement : supplied) {
			remaining.put(statement.getSubject(), statement);
		}
		List<Record> expected = new ArrayList<>(supplied.size());
		for (Record record : journal.records()) {
			assertTrue(record.isStatementOperation());
			assertEquals(addition, record.isAddition());
			assertTrue(record.isExplicit());
			Statement suppliedStatement = remaining.remove(record.getStatement().getSubject());
			assertNotNull(suppliedStatement, "A transaction must publish each supplied statement exactly once");
			assertEquals(suppliedStatement, record.getStatement());
			expected.add(new Record(addition, true, suppliedStatement));
		}
		assertTrue(remaining.isEmpty());
		ByteArrayOutputStream expectedBytes = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(expectedBytes, expected, previous, generation);
		assertArrayEquals(expectedBytes.toByteArray(), actualBytes,
				"Default public bulk writes must retain the exact existing journal encoding");
	}

	private static void logNativeStructure(TripleStore triples, String phase, long logical) throws IOException {
		List<String> observations = triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			List<String> lines = new ArrayList<>();
			List<String> names = new ArrayList<>();
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), statistics));
			lines.add(statistics(phase, logical, "<catalog>", statistics));
			var handle = stack.mallocPointer(1);
			E(mdb_cursor_open(transaction, database.get(0), handle));
			long cursor = handle.get(0);
			MDBVal key = MDBVal.malloc(stack);
			MDBVal value = MDBVal.malloc(stack);
			try {
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result == MDB_SUCCESS) {
					ByteBuffer keyBytes = Objects.requireNonNull(key.mv_data()).duplicate();
					byte[] ownedKey = new byte[keyBytes.remaining()];
					keyBytes.get(ownedKey);
					if (Arrays.equals(ownedKey, LmdbBackupCatalogTestSupport.KEY)) {
						ByteBuffer bytes = Objects.requireNonNull(value.mv_data()).duplicate();
						byte[] record = new byte[bytes.remaining()];
						bytes.get(record);
						byte[] pack = LmdbBackupCatalogTestSupport.unpack(record);
						lines.add("BACKUP_NATIVE_CATALOG,phase=" + phase + ",transaction=" + logical
								+ ",mv_size=" + record.length + ",pack_bytes=" + pack.length);
					} else {
						names.add(new String(ownedKey, StandardCharsets.UTF_8));
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				E(result);
			} finally {
				mdb_cursor_close(cursor);
			}
			for (String name : names) {
				E(mdb_dbi_open(transaction, name, 0, database));
				E(mdb_stat(transaction, database.get(0), statistics));
				lines.add(statistics(phase, logical, name, statistics));
				if (!name.startsWith(LmdbBackupOutbox.DATABASE_NAME)) {
					continue;
				}
				E(mdb_cursor_open(transaction, database.get(0), handle));
				cursor = handle.get(0);
				try {
					int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
					while (result == MDB_SUCCESS) {
						ByteBuffer bytes = Objects.requireNonNull(key.mv_data())
								.duplicate()
								.order(ByteOrder.BIG_ENDIAN);
						if (bytes.remaining() == 2 * Long.BYTES && bytes.getLong() == logical) {
							lines.add("BACKUP_NATIVE_CHUNK,phase=" + phase + ",transaction=" + logical + ",database="
									+ name + ",chunk=" + bytes.getLong() + ",mv_size=" + value.mv_size());
						}
						result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
					}
					E(result);
				} finally {
					mdb_cursor_close(cursor);
				}
			}
			return lines;
		});
		observations.forEach(System.out::println);
	}

	private static String statistics(String phase, long logical, String name, MDBStat statistics) {
		return "BACKUP_NATIVE_LAYOUT,phase=" + phase + ",transaction=" + logical + ",database=" + name
				+ ",branch=" + statistics.ms_branch_pages() + ",leaf=" + statistics.ms_leaf_pages()
				+ ",overflow=" + statistics.ms_overflow_pages() + ",entries=" + statistics.ms_entries();
	}
